# Create the transform script that reproduces all demo pairs
# Rule: Extract shapes from above and below gray row, preserve colors exactly

def transform(grid):
    # Parse grid to find gray row (row 5)
    rows = len(grid)
    gray_row_idx = rows // 2 - 1  # Row 5 (0-indexed)

    # Cells above gray (rows 0-4)
    above_cells = grid[:gray_row_idx+1]

    # Cells below gray (rows 6-8)
    below_cells = grid[gray_row_idx+2:]

    # Find all non-background, non-gray colors above
    non_gray_colors = []
    for row in above_cells:
        for col, color in enumerate(row):
            if color < 2:  # Only colors 1, 2, 3, etc
                non_gray_colors.append((color, col))

    # Remove duplicates and find rightmost for each color
    by_color_above = {}
    for color, col in non_gray_colors:
        if color not in by_color_above:
            by_color_above[color] = []
        by_color_above[color].append(col)

    # Get rightmost column for each color above
    rightmost_cols = {}
    for color, cols in by_color_above.items():
        rightmost_cols[color] = max(cols)

    # Extract shapes from above (all cells, not just rightmost)
    # Group by color, find bbox for each color shape
    color_shapes_above = {}
    for color, cols in by_color_above.items():
        # Get all rows with this color
        rows_with_color = []
        cols_with_color = set(cols)
        for r, row in enumerate(above_cells):
            row_cols = [c for c in range(len(row)) if row[c] == color and row[c] < 2]
            if row_cols:
                rows_with_color.append((r, row_cols))

        # Extract shape
        color_shapes_above[color] = rows_with_color

    # Find rightmost above cells to preserve
    rightmost_all = []
    for r, row in enumerate(above_cells):
        for c, color in enumerate(row):
            if color < 2:
                rightmost_all.append((r, c, color))

    # Now extract shapes from below
    color_shapes_below = {}
    # Group by color
    cells_by_color = {}
    for r, row in enumerate(below_cells):
        for c, color in enumerate(row):
            if color < 2:
                if color not in cells_by_color:
                    cells_by_color[color] = []
                cells_by_color[color].append((r, c))

    for color, cells in cells_by_color.items():
        color_shapes_below[color] = cells

    # Build output grid 9x15
    output = [[0]*15 for _ in range(9)]

    # Middle tier (rows 3-5): preserve below shapes
    for color, cells in color_shapes_below.items():
        for r_offset, c in cells:
            output[3 + r_offset][c] = color

    # Bottom tier (rows 6-8): preserve rightmost above pattern
    for r, c, color in rightmost_all:
        output[6 + r][c] = color

    return output

